	Buckets: []TimeBucket{
		{Start: 0, End: 10, TxCount: 5, DistinctTxIDs: 3, Blocks: 2},
		{Start: 10, End: 20},
		{Start: 20, End: 30, TxCount: 1, DistinctTxIDs: 1, Blocks: 1},
